from pathlib import Path
import base64
import gzip
import hashlib
import json
import shutil

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / '_site'
SOURCE = ROOT / 'index.html'

V344_SHA256 = 'b68a3e463f3d0610bbdd3dad15472cf38f46dd403cc3ab6bf809da87e79a6eda'
V345_SHA256 = 'e52a71b2f376d334d5f9efeaf7017be9c338e46a54d055df669a5c5f28ae6f2d'

OPS_B64 = ''''''

def sha256_text(text):
    return hashlib.sha256(text.encode('utf-8')).hexdigest()

def convert(text):
    sha = sha256_text(text)
    if sha == V345_SHA256:
        return text
    if sha != V344_SHA256:
        raise RuntimeError(f'unexpected index.html SHA256: {sha}')

    src = text.splitlines(keepends=True)
    changes = json.loads(gzip.decompress(base64.b64decode(OPS_B64)).decode('utf-8'))
    out = []
    pos = 0
    for tag, i1, i2, new_text in changes:
        if i1 < pos:
            raise RuntimeError('overlapping patch ranges')
        out.extend(src[pos:i1])
        out.append(new_text)
        pos = i2
    out.extend(src[pos:])
    result = ''.join(out)

    final_sha = sha256_text(result)
    if final_sha != V345_SHA256:
        raise RuntimeError(f'V3.4.5 SHA mismatch: {final_sha}')
    return result

def main():
    if not SOURCE.exists():
        raise RuntimeError('missing root index.html')
    text = SOURCE.read_text(encoding='utf-8')
    v345 = convert(text)
    SOURCE.write_text(v345, encoding='utf-8')

    if SITE.exists():
        shutil.rmtree(SITE)
    SITE.mkdir(parents=True)
    shutil.copy2(SOURCE, SITE / 'index.html')
    (SITE / '.nojekyll').write_text('', encoding='utf-8')
    print('DO V3.4.5 exact local file generated and ready for direct Pages publish')

if __name__ == '__main__':
    main()
